      receivedThroughChida: false,
      visibility: "خصوصی پروژه",
      localStatus: "ثبت محلی",
      externalEffect: "none",
      networkUsed: false,
      aiUsed: false,
      sendAuthorized: false,
      supplierNotified: false,
      sharedWithSupplier: false,
      externalActionAttempted: false,
